create table if not exists public.demo_encounters (
  idx integer primary key,
  enc_id text not null unique,
  age text not null,
  age_group text not null,
  gender text not null,
  race text not null,
  stay smallint not null,
  meds smallint not null,
  inpatient smallint not null,
  er smallint not null,
  a1c text not null,
  diag text not null,
  prob double precision not null check (prob >= 0 and prob <= 1),
  tier text not null,
  resources jsonb not null default '[]'::jsonb,
  top_factors jsonb not null default '[]'::jsonb,
  actual smallint not null check (actual in (0, 1))
);

create index if not exists demo_encounters_prob_idx on public.demo_encounters (prob);
create index if not exists demo_encounters_age_group_idx on public.demo_encounters (age_group);

create table if not exists public.demo_governance (
  singleton boolean primary key default true check (singleton),
  summary jsonb not null,
  models jsonb not null,
  fairness jsonb not null,
  selected_model text not null
);

alter table public.demo_encounters enable row level security;
alter table public.demo_governance enable row level security;
revoke all on public.demo_encounters from anon, authenticated;
revoke all on public.demo_governance from anon, authenticated;
grant select on public.demo_encounters to anon, authenticated;
grant select on public.demo_governance to anon, authenticated;

create policy "Public read of de-identified demo encounters"
  on public.demo_encounters for select to anon, authenticated using (true);
create policy "Public read of demo governance summary"
  on public.demo_governance for select to anon, authenticated using (true);

on conflict (idx) do nothing;

